layer.css:
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgb(247, 249, 250); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: rgb(3, 102, 214); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(3, 102, 214); text-decoration-thickness: auto; text-underline-offset: auto; transition: transform 0.15s ease-out }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-size: 20px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="header"] { border-bottom: 1px solid rgb(234, 234, 234); border-top: none }
[data-ryt="button"] { color: var(--ryt-text); background-color: rgb(239, 239, 239); border-radius: 4px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: all }
[data-ryt="nav"] a:hover { color: var(--ryt-text); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { transform: scale(1.1); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
